statement:
One table logs app activity:

- `app_events(event_id, user_id, event_timestamp, event_type, session_id, event_value)`: one row per event; `event_id` is unique. `event_type` is one of `'app_open'`, `'click'`, `'scroll'`, `'purchase'`, `'app_close'`. Events sharing a `session_id` form one session of one user. `event_value` is the amount for a purchase, the pixels for a scroll, and `null` otherwise.

A session is a **zombie** when all of these hold:

- its duration, the whole number of minutes from its earliest to its latest event (as `TIMESTAMPDIFF(MINUTE, ...)` counts them), is greater than 30;
- it has at least 5 `scroll` events;
- its number of `click` events divided by its number of `scroll` events is strictly below 0.20;
- it contains no `purchase` event.

Report each zombie session with the columns `session_id`, `user_id`, `session_duration_minutes` and `scroll_count`, sorted by `scroll_count` descending and then by `session_id` ascending.

validator:
function validate(input) {
  const [{ app_events = [] }] = input;
  const types = ['app_open', 'click', 'scroll', 'purchase', 'app_close'];
  const ids = new Set(), owner = new Map();
  for (const [id, user, time, type, session, value] of app_events) {
    if ([id, user, time, type, session].includes(null)) return 'Only event_value may be null.';
    if (ids.has(id)) return `event_id ${id} appears twice.`;
    ids.add(id);
    if (!types.includes(type)) return `event_type ${type} is not a known event type.`;
    if (!/^\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}$/.test(time)) return `event_timestamp ${time} must look like 2024-03-01 10:00:00.`;
    if ((type === 'scroll' || type === 'purchase') !== (value !== null)) return `event ${id}: only scroll and purchase events carry an event_value.`;
    const key = String(session).toLowerCase();
    if (owner.has(key) && owner.get(key) !== user) return `Session ${session} belongs to two users.`;
    owner.set(key, user);
  }
  return null;
}

generator:
function generate(rand, size) {
  const small = size === 'small';
  const pick = list => list[Math.floor(rand() * list.length)];
  const pad = n => String(n).padStart(2, '0');
  const stamp = minutes => {
    const d = new Date(Date.UTC(2024, 2, 1) + minutes * 60000);
    return `${d.getUTCFullYear()}-${pad(d.getUTCMonth() + 1)}-${pad(d.getUTCDate())} ${pad(d.getUTCHours())}:${pad(d.getUTCMinutes())}:00`;
  };
  // Scroll-heavy sessions so that zombies, boundary ratios and boundary durations all show up.
  const types = ['scroll', 'scroll', 'scroll', 'scroll', 'scroll', 'click', 'app_open', 'app_close', 'purchase'];
  const app_events = [];
  const sessions = small ? 1 + Math.floor(rand() * 2) : 200;
  let budget = small ? Math.floor(rand() * 9) : 2000;
  for (let s = 1; s <= sessions && budget > 0; s++) {
    const session = small ? `S${s}` : `S${String(s).padStart(4, '0')}`;
    const user = small ? pick([201, 202]) : 200 + Math.floor(rand() * 80);
    const start = small ? pick([600, 1430]) : Math.floor(rand() * 60 * 24 * 20);
    const events = s === sessions ? budget : Math.min(budget, small ? 1 + Math.floor(rand() * 8) : 5 + Math.floor(rand() * 11));
    budget -= events;
    for (let e = 0; e < events; e++) {
      const type = pick(types);
      const offset = small ? pick([0, 5, 10, 25, 30, 31, 45]) : Math.floor(rand() * 61);
      const value = type === 'scroll' ? 100 + Math.floor(rand() * 10) * 100 : type === 'purchase' ? 5 + Math.floor(rand() * 95) : null;
      app_events.push([app_events.length + 1, user, stamp(start + offset), type, session, value]);
    }
  }
  return [{ app_events }];
}
